/* The glyphs of the Respect speed label, rasterised (speed_glyphs.c is generated by
 * scripts/gen_speed_glyphs.py). */
#ifndef ES_SPEED_GLYPHS_H
#define ES_SPEED_GLYPHS_H

#define ES_SPEED_NGLYPHS 13

typedef struct {
    char ch;
    int w, h;                 /* bounding box of the coverage mask */
    int adv;                  /* advance, in em units (64 px em) */
    int xoff, yoff;           /* offset of the mask from the pen position / the top of the line */
    const unsigned char *a;   /* h rows of w bytes, 0..255 coverage */
} es_glyph;

extern const es_glyph es_speed_glyphs[ES_SPEED_NGLYPHS];
extern const int es_speed_em, es_speed_ascent, es_speed_digit_h;

#endif
